use dep::fuzk;
use mimc::mimc_bn254;
use schnorr::verify_signature;
use std::embedded_curve_ops::EmbeddedCurvePoint;

#[export]
fn main(
    address: pub Field,

    //deposit order note
    deposit_out_note: pub Field,
    deposit_out_note_footer: pub Field,
    deposit_out_rho: Field,

    //order
    out_asset: pub Field,
    out_amount: pub Field,
    in_asset: Field,
    min_in_amount: Field,

    //fee
    fee_ratio: pub Field,

    //swap in 
    in_note_footer: pub Field,
    in_rho: Field,

    pub_key: [Field; 2],
    signature: [u8; 64]
) {
    out_amount.assert_max_bit_size::<252>();

    fuzk::assert_note(
        deposit_out_note,
        address,
        out_asset,
        out_amount,
        deposit_out_rho,
        fee_ratio,
        pub_key,
        Option::some(3),
        true,
        true
    );

    fuzk::assert_note_footer(deposit_out_note_footer, deposit_out_rho, pub_key);

    fuzk::assert_note_footer(in_note_footer, in_rho, pub_key);

    let signature_domain = 10012;

    let m = mimc_bn254([
        signature_domain,
        address,
        deposit_out_note,
        fee_ratio,
        in_asset,
        min_in_amount,
        in_note_footer
    ]);


    let pub_key_point: EmbeddedCurvePoint = EmbeddedCurvePoint { x: pub_key[0], y: pub_key[1] };
    let v = verify_signature(pub_key_point, fuzk::signature_scalars(signature), m);

    assert(v);
}

