use dep::std;
use mimc::mimc_bn254;
use std::embedded_curve_ops::EmbeddedCurveScalar;
use std::field::bn254::assert_gt;

pub fn assert_amounts<let N: u32>(amounts: [Field; N]) {
    for amount in amounts {
        if (amount != 0){
            amount.assert_max_bit_size::<252>();
            assert_gt(amount, 0);
        }
    }
}

// signature is s || e, each a 32-byte big-endian grumpkin scalar (bb.js schnorrConstructSignature output)
pub fn signature_scalars(signature: [u8; 64]) -> (EmbeddedCurveScalar, EmbeddedCurveScalar) {
    (scalar_from_be_bytes(signature, 0), scalar_from_be_bytes(signature, 32))
}

fn scalar_from_be_bytes(bytes: [u8; 64], offset: u32) -> EmbeddedCurveScalar {
    let mut hi: Field = 0;
    let mut lo: Field = 0;
    for i in 0..16 {
        hi = hi * 256 + bytes[offset + i] as Field;
        lo = lo * 256 + bytes[offset + 16 + i] as Field;
    }
    EmbeddedCurveScalar::new(lo, hi)
}

pub fn note_footer(rho: Field, pub_key: [Field; 2]) -> Field {
    mimc_bn254(
        [
        mimc_bn254([rho]),
        pub_key[0],
        pub_key[1]
    ]
    )
}


pub fn assert_note(
    note: Field,
    address: Field,
    asset: Field,
    amount: Field,
    rho: Field,
    fee_ratio: Field,
    pub_key: [Field; 2],
    note_domain_separator: Option<Field>,
    is_dark_swap: bool,
    is_order: bool
) {
    assert_note_with_footer(
        note,
        address,
        asset,
        amount,
        fee_ratio,
        note_footer(rho, pub_key),
        note_domain_separator,
        is_dark_swap,
        is_order
    )
}

pub fn assert_note_footer(in_note_footer: Field, rho: Field, pub_key: [Field; 2]) {
    assert(in_note_footer == note_footer(rho, pub_key));
}

pub fn assert_note_with_footer(
    note: Field,
    address: Field,
    asset: Field,
    amount: Field,
    fee_ratio: Field,
    footer: Field,
    note_domain_separator: Option<Field>,
    is_dark_swap: bool,
    is_order:bool
) {
    assert(
        note == if is_dark_swap {
            if is_order {
                mimc_bn254([
                    note_domain_separator.unwrap(),
                    address,
                    asset,
                    amount,
                    fee_ratio,
                    footer
                ])
            } else {
                mimc_bn254([
                    note_domain_separator.unwrap(),
                    address,
                    asset,
                    amount,
                    footer
                ])
            }
        } else {
            mimc_bn254([
                note_domain_separator.unwrap(),
                asset,
                amount,
                footer
            ])
        }
    );
}

pub fn assert_note_with_membership(
    merkle_root: Field,
    merkle_index: [bool; 32],
    merkle_path: [Field; 32],
    address: Field,
    note: Field,
    asset: Field,
    amount: Field,
    rho: Field,
    fee_ratio: Field,
    pub_key: [Field; 2],
    note_domain_separator: Option<Field>,
    is_dark_swap: bool,
    is_order:bool
) {
    assert_note(note,address,asset, amount, rho, fee_ratio,pub_key, note_domain_separator, is_dark_swap, is_order);
    assert(merkle_root == compute_merkle_root(note, merkle_index, merkle_path));
}

pub fn assert_nullifier(nullifier: Field, rho: Field, pub_key: [Field; 2]) {
    assert(
        nullifier == mimc_bn254(
            [
            rho,
            pub_key[0],
            pub_key[1]
        ]
        )
    );
}

pub fn compute_merkle_root(leaf: Field, merkle_index: [bool; 32], merkle_path: [Field; 32]) -> Field {

    let mut merkle_root = mimc_bn254([0x0, leaf]);
    for i in 0..32 {
        let left = if !merkle_index[i] {
            merkle_root
        } else {
            merkle_path[i]
        };
        let right = if merkle_index[i] {
            merkle_root
        } else {
            merkle_path[i]
        };

        let next_merkle_root = mimc_bn254([0x01, left, right]);

        if merkle_path[i] != 0 {
            merkle_root = next_merkle_root;
        }
    }
    merkle_root
}

#[test]
fn test_assert_amounts() {
    let amount_1: Field = 1;
    let amount_2: Field = 2;

    assert_amounts([amount_1, amount_2]);
}

#[test(should_fail)]
fn test_assert_amounts_fail() {
    let amount_1: Field = 1;
    let amount_2: Field = -2;
    let amount_3: Field = -3;

    assert_amounts([amount_1, amount_2, amount_3]);
}

55.source:
use poseidon::poseidon2::Poseidon2;
use std::embedded_curve_ops::{EmbeddedCurvePoint, EmbeddedCurveScalar, multi_scalar_mul};

global TWO_POW_128: Field = 0x100000000000000000000000000000000;

/// Domain separation tag (DST) for the challenge hash of this Schnorr scheme.
///
/// Defined as `poseidon2_hash_bytes("schnorr_grumpkin_poseidon2")` where the byte-packing
/// is: little-endian into 31-byte chunks, then Poseidon2 of the resulting field elements
/// (length-1 input here since the source string fits in a single chunk). The derivation is
/// pinned by `test::dst_matches_derivation`. Native signers consuming this library must
/// mirror the same constant.
///
/// Including the DST as the first input to the challenge hash binds every signature to the
/// "Schnorr over grumpkin with Poseidon2" scheme, preventing cross-protocol reinterpretation
/// of an unrelated Poseidon2 output as a valid Schnorr challenge.
pub global SCHNORR_CHALLENGE_DST: Field =
    0x024c76938ed06b8ec1d9094b1013d190baa4011372f0604643bda812a63b832e;

pub fn verify_signature(
    public_key: EmbeddedCurvePoint,
    signature: (EmbeddedCurveScalar, EmbeddedCurveScalar),
    message: Field,
) -> bool {
    let (sig_s, sig_e) = signature;
    let mut is_ok = is_on_curve(public_key);

    let zero = EmbeddedCurveScalar::new(0, 0);
    if ((sig_s != zero) & (sig_e != zero)) {
        let (r_is_infinite, e_computed) =
            calculate_signature_challenge(public_key, sig_s, sig_e, message);

        is_ok &= !r_is_infinite;
        let sig_e_field = sig_e.lo + sig_e.hi * TWO_POW_128;
        is_ok &= e_computed == sig_e_field;
    } else {
        is_ok = false;
    }
    is_ok
}

pub fn assert_valid_signature(
    public_key: EmbeddedCurvePoint,
    signature: (EmbeddedCurveScalar, EmbeddedCurveScalar),
    message: Field,
) {
    let (sig_s, sig_e) = signature;

    assert(is_on_curve(public_key));
    let zero = EmbeddedCurveScalar::new(0, 0);
    assert(sig_s != zero);
    assert(sig_e != zero);

    let (r_is_infinite, e_computed) =
        calculate_signature_challenge(public_key, sig_s, sig_e, message);

    assert(!r_is_infinite);
    let sig_e_field = sig_e.lo + sig_e.hi * TWO_POW_128;
    assert(e_computed == sig_e_field);
}

/// e = Poseidon2(SCHNORR_CHALLENGE_DST, R.x, pubkey.x, pubkey.y, message)
///
/// Mirrors the native C++ implementation: the Poseidon2 sponge operates over the BN254 scalar
/// field (= grumpkin base field = Noir's Field). Since Field modulus < grumpkin scalar modulus,
/// the challenge embeds losslessly into the grumpkin scalar field for the signature equation.
fn calculate_signature_challenge(
    public_key: EmbeddedCurvePoint,
    sig_s: EmbeddedCurveScalar,
    sig_e: EmbeddedCurveScalar,
    message: Field,
) -> (bool, Field) {
    let g1 = EmbeddedCurvePoint::generator();
    let r = multi_scalar_mul([g1, public_key], [sig_s, sig_e]);
    let e = Poseidon2::hash(
        [SCHNORR_CHALLENGE_DST, r.x, public_key.x, public_key.y, message],
        5,
    );
    (r.is_infinite(), e)
}

fn is_on_curve(point: EmbeddedCurvePoint) -> bool {
    point.y * point.y == point.x * point.x * point.x - 17
}

mod test {
    use super::{SCHNORR_CHALLENGE_DST, verify_signature};
    use poseidon::poseidon2::Poseidon2;
    use std::embedded_curve_ops::{EmbeddedCurvePoint, EmbeddedCurveScalar};

    #[test]
    fn zero_signature() {
        let public_key: EmbeddedCurvePoint = EmbeddedCurvePoint::generator();
        let signature: (EmbeddedCurveScalar, EmbeddedCurveScalar) =
            (EmbeddedCurveScalar::new(0, 0), EmbeddedCurveScalar::new(0, 0));
        let message: Field = 0x1234;
        let verified = verify_signature(public_key, signature, message);
        assert(!verified);
    }

    // Recompute the DST from its source string and assert it matches the pinned constant.
    // Native signers consuming this library must derive the same value; if either side
    // drifts, signatures stop verifying across the native / in-circuit boundary.
    #[test]
    fn dst_matches_derivation() {
        let src = "schnorr_grumpkin_poseidon2".as_bytes();
        assert(src.len() <= 31);
        let mut packed: Field = 0;
        let mut mul: Field = 1;
        for i in 0..src.len() {
            packed += (src[i] as Field) * mul;
            mul *= 256;
        }
        let derived = Poseidon2::hash([packed], 1);
        assert_eq(derived, SCHNORR_CHALLENGE_DST);
    }

    // Pinned test vector mirroring the C++ `schnorr.pinned_test_vector_small` test.
    #[test]
    fn pinned_vector_small() {
        let public_key = EmbeddedCurvePoint::new(
            0x2c39bbbde2d0ffcb5c4317dcbfa1771cf554a2f33c647446632fa707a5bf5f3f,
            0x2b9c81935298af5ebe22f1a7279bb76781e6cadba3fb6c5c41ed942392dc687c,
        );
        let sig_s = EmbeddedCurveScalar::new(
            0x5fd1ac0ad411110674830c54cb506212,
            0x281906862cdb4e0efec7226d757fe803,
        );
        let sig_e = EmbeddedCurveScalar::new(
            0x6c368959f958e525d761d06c47fd2ad6,
            0x013f6a902c6c0efafdadbd4de409690d,
        );
        let message: Field = 0x2bc;
        assert(verify_signature(public_key, (sig_s, sig_e), message));
    }

    // Pinned test vector mirroring the C++ `schnorr.pinned_test_vector_large` test.
    #[test]
    fn pinned_vector_large() {
        let public_key = EmbeddedCurvePoint::new(
            0x065812e335a97c2108ea8cf4ccfe2f9dd6b117a0714f5e18461575be93f61da6,
            0x1a915003e8ec534f9a15d926a7ded478e178468ccc4f28e236e67450a55ac622,
        );
        let sig_s = EmbeddedCurveScalar::new(
            0xf3bc3b7147acb9c621fd9f72dbf15ffa,
            0x08599f379f0301dfefdbd0272554454d,
        );
        let sig_e = EmbeddedCurveScalar::new(
            0x97065383ebbbd76620398792bd259bc2,
            0x2ceaee87f45b7a417f0ffb05451a8c92,
        );
        let message: Field = 0x0123456789abcdef0fedcba9876543210123456789abcdef0fedcba987654321;
        assert(verify_signature(public_key, (sig_s, sig_e), message));
    }
}

mod bench {
    use super::{assert_valid_signature, verify_signature};
    use std::embedded_curve_ops::{EmbeddedCurvePoint, EmbeddedCurveScalar};

    #[export]
    pub fn bench_verify_signature(
        public_key: EmbeddedCurvePoint,
        signature: (EmbeddedCurveScalar, EmbeddedCurveScalar),
        message: Field,
    ) -> bool {
        verify_signature(public_key, signature, message)
    }

    #[export]
    pub fn bench_assert_valid_signature(
        public_key: EmbeddedCurvePoint,
        signature: (EmbeddedCurveScalar, EmbeddedCurveScalar),
        message: Field,
    ) {
        assert_valid_signature(public_key, signature, message)
    }
}

63.source:
use std::default::Default;
use std::hash::Hasher;

global RATE: u32 = 3;

pub struct Poseidon2 {
    cache: [Field; 3],
    state: [Field; 4],
    cache_size: u32,
    squeeze_mode: bool, // 0 => absorb, 1 => squeeze
}

impl Poseidon2 {
    #[no_predicates]
    pub fn hash<let N: u32>(input: [Field; N], message_size: u32) -> Field {
        Poseidon2::hash_internal(input, message_size)
    }

    pub(crate) fn new(iv: Field) -> Poseidon2 {
        let mut result =
            Poseidon2 { cache: [0; 3], state: [0; 4], cache_size: 0, squeeze_mode: false };
        result.state[RATE] = iv;
        result
    }

    fn perform_duplex(&mut self) {
        // add the cache into sponge state
        self.state[0] += self.cache[0];
        self.state[1] += self.cache[1];
        self.state[2] += self.cache[2];
        self.state = crate::poseidon2_permutation(self.state);
    }

    fn absorb(&mut self, input: Field) {
        assert(!self.squeeze_mode);
        if self.cache_size == RATE {
            // If we're absorbing, and the cache is full, apply the sponge permutation to compress the cache
            self.perform_duplex();
            self.cache[0] = input;
            self.cache_size = 1;
        } else {
            // If we're absorbing, and the cache is not full, add the input into the cache
            self.cache[self.cache_size] = input;
            self.cache_size += 1;
        }
    }

    fn squeeze(&mut self) -> Field {
        assert(!self.squeeze_mode);
        // If we're in absorb mode, apply sponge permutation to compress the cache.
        self.perform_duplex();
        self.squeeze_mode = true;

        // Pop one item off the top of the permutation and return it.
        self.state[0]
    }

    fn hash_internal<let N: u32>(input: [Field; N], in_len: u32) -> Field {
        let two_pow_64 = 18446744073709551616;
        let iv: Field = (in_len as Field) * two_pow_64;
        let mut state = [0; 4];
        state[RATE] = iv;

        if std::runtime::is_unconstrained() {
            for i in 0..(in_len / RATE) {
                state[0] += input[i * RATE];
                state[1] += input[i * RATE + 1];
                state[2] += input[i * RATE + 2];
                state = crate::poseidon2_permutation(state);
            }

            // handle remaining elements after last full RATE-sized chunk
            let num_extra_fields = in_len % RATE;
            if num_extra_fields != 0 {
                let remainder_start = in_len - num_extra_fields;
                state[0] += input[remainder_start];
                if num_extra_fields > 1 {
                    state[1] += input[remainder_start + 1];
                }
            }
        } else {
            let mut states: [[Field; 4]; N / RATE + 1] = [[0; 4]; N / RATE + 1];
            states[0] = state;

            // process all full RATE-sized chunks, storing state after each permutation
            for chunk_idx in 0..(N / RATE) {
                for i in 0..RATE {
                    state[i] += input[chunk_idx * RATE + i];
                }
                state = crate::poseidon2_permutation(state);
                states[chunk_idx + 1] = state;
            }

            // get state at the last full block before in_len
            let first_partially_filled_chunk = in_len / RATE;
            state = states[first_partially_filled_chunk];

            // handle remaining elements after last full RATE-sized chunk
            let remainder_start = (in_len / RATE) * RATE;
            for j in 0..RATE {
                let idx = remainder_start + j;
                if idx < in_len {
                    state[j] += input[idx];
                }
            }
        }

        // always run final permutation unless we just completed a full chunk
        // still need to permute once if in_len is 0
        if (in_len == 0) | (in_len % RATE != 0) {
            state = crate::poseidon2_permutation(state);
        };

        state[0]
    }
}

pub struct Poseidon2Hasher {
    _state: [Field],
}

impl Hasher for Poseidon2Hasher {
    fn finish(self) -> Field {
        let iv: Field = (self._state.len() as Field) * 18446744073709551616; // iv = (self._state.len() << 64)
        let mut sponge = Poseidon2::new(iv);
        for i in 0..self._state.len() {
            sponge.absorb(self._state[i]);
        }
        sponge.squeeze()
    }

    fn write(&mut self, input: Field) {
        self._state = self._state.push_back(input);
    }
}

impl Default for Poseidon2Hasher {
    fn default() -> Self {
        Poseidon2Hasher { _state: @[] }
    }
}
